def split_by_type(apps, schema_editor):
    Batch = apps.get_model("api", "SettlementBatch")
    Item = apps.get_model("api", "SettlementBatchItem")
    for batch in Batch.objects.order_by("year", "month", "number"):
        types = set(Item.objects.filter(batch=batch).values_list("advance__advance_type", flat=True))
        if not types or types == {"general"}:
            batch.advance_type = "general"
            batch.save(update_fields=["advance_type"])
            continue
        if types == {"term"}:
            batch.advance_type = "term"
            batch.save(update_fields=["advance_type"])
            continue
        # both kinds: this batch keeps the Salary Advances, a new Term Loan batch takes the Term Loans
        batch.advance_type = "general"
        batch.save(update_fields=["advance_type"])
        taken = Batch.objects.filter(month=batch.month, year=batch.year, advance_type="term").values_list("number", flat=True)
        number = max(taken, default=0) + 1
        term = Batch.objects.create(
            month=batch.month,
            year=batch.year,
            advance_type="term",
            number=number,
            **{f: getattr(batch, f) for f in STAGE_FIELDS},
        )
        Item.objects.filter(batch=batch, advance__advance_type="term").update(batch=term)


